import json

def primes_upto(n):
    s = bytearray([1]) * (n + 1)
    s[0] = s[1] = 0
    for i in range(2, int(n ** 0.5) + 1):
        if s[i]:
            s[i * i::i] = bytearray(len(s[i * i::i]))
    return [i for i, v in enumerate(s) if v]

# admissible n: no prime divisor < 2015 (n=1, primes >= 2017, products of such primes)
ps = [p for p in primes_upto(12000) if p >= 2015]
ns = [1] + ps[:400] + [2017 * 2017, 2017 * 2027, 2029 * 2039, 2017 ** 3]

def ok(a, b, c):
    for n in ns:
        m = n + c
        if (pow(a, n, m) + pow(b, n, m) + n) % m:
            return False
    return True

sols = []
B = 40
for c in range(1, B + 1):
    for a in range(1, B + 1):
        for b in range(a, B + 1):
            if ok(a, b, c):
                sols.append((a, b, c))
                if a != b:
                    sols.append((b, a, c))

if sols:
    ans = "; ".join(str(s) for s in sorted(set(sols)))
    print(json.dumps({
        "final_answer": ans,
        "evidence": {
            "search_bound": B,
            "n_tested": len(ns),
            "solutions": sorted(set(sols)),
            "reason": "n+c prime large => a^(1-c)+b^(1-c)=c forces c=2,a=b=1; verified n+2 | n+2"
        }
    }))
else:
    print("UNSUPPORTED")
